returned-reference-control.source:
// Source acceptance for both tiers. Expected output is in expected-stdout.txt.
// Uses the actual mounted standard library; no substitute Once/Atomic bodies.
mount core.sync.once.Once;
mount core.sync.once.OnceLock;
mount core.runtime.supervisor.root_supervisor;

type ReferenceParcel<T> is Missing | Present(T);
type ReferenceRecord is { padding: Int, value: Int };
implement ReferenceRecord {
    fn read(&self) -> Int { self.value }
}

fn projection_borrow<T>(p: &ReferenceParcel<T>) -> ReferenceParcel<&T> {
    match p {
        ReferenceParcel.Present(ref value) => ReferenceParcel.Present(value),
        ReferenceParcel.Missing => ReferenceParcel.Missing,
    }
}
fn projection_project<T>(p: ReferenceParcel<T>) -> T {
    match p {
        ReferenceParcel.Present(value) => value,
        ReferenceParcel.Missing => panic("missing reference payload"),
    }
}
fn projection_first(p: &ReferenceParcel<ReferenceRecord>) -> &ReferenceRecord {
    projection_project(projection_borrow(p))
}
fn projection_forward(p: &ReferenceParcel<ReferenceRecord>) -> &ReferenceRecord {
    projection_first(p)
}
fn projection_scalar(p: &ReferenceParcel<Int>) -> &Int {
    projection_project(projection_borrow(p))
}
fn projection_scalar_forward(p: &ReferenceParcel<Int>) -> &Int { projection_scalar(p) }
fn projection_value(p: ReferenceParcel<Int>) -> Int { projection_project(p) }
fn projection_mut(p: &mut ReferenceParcel<Int>) -> &mut Int {
    match p {
        ReferenceParcel.Present(ref mut value) => value,
        ReferenceParcel.Missing => panic("missing mutable payload"),
    }
}
fn projection_mut_forward(p: &mut ReferenceParcel<Int>) -> &mut Int { projection_mut(p) }
fn projection_write(p: &mut ReferenceParcel<Int>, replacement: Int) {
    *projection_mut_forward(p) = replacement;
}
fn projection_record_mut(p: &mut ReferenceParcel<ReferenceRecord>) -> &mut ReferenceRecord {
    match p {
        ReferenceParcel.Present(ref mut value) => value,
        ReferenceParcel.Missing => panic("missing mutable record"),
    }
}
fn projection_record_mut_forward(p: &mut ReferenceParcel<ReferenceRecord>) -> &mut ReferenceRecord {
    projection_record_mut(p)
}
fn projection_record_write(p: &mut ReferenceParcel<ReferenceRecord>, replacement: Int) {
    projection_record_mut_forward(p).value = replacement;
}

static mut REFERENCE_ONCE_COUNT: Int = 0;
static mut REFERENCE_SCALAR_COUNT: Int = 0;
static mut REFERENCE_RECORD_COUNT: Int = 0;
static REFERENCE_SCALAR_CELL: OnceLock<Int> = OnceLock.new();
static REFERENCE_RECORD_CELL: OnceLock<ReferenceRecord> = OnceLock.new();

fn reference_scalar_initialize() -> Int {
    REFERENCE_SCALAR_COUNT = REFERENCE_SCALAR_COUNT + 1;
    37
}
fn reference_record_initialize() -> ReferenceRecord {
    REFERENCE_RECORD_COUNT = REFERENCE_RECORD_COUNT + 1;
    ReferenceRecord { padding: 11, value: 73 }
}
fn reference_record_accessor() -> &ReferenceRecord {
    REFERENCE_RECORD_CELL.get_or_init(reference_record_initialize)
}
fn reference_record_root() -> &ReferenceRecord { reference_record_accessor() }

fn main() {
    print("reference_projection_begin");
    let mut record: ReferenceParcel<ReferenceRecord> = ReferenceParcel.Present(ReferenceRecord { padding: 11, value: 73 });
    let field = projection_forward(&record).value + 0;
    let method = projection_forward(&record).read() + 0;
    let mut scalar: ReferenceParcel<Int> = ReferenceParcel.Present(73);
    let scalar_before = *projection_scalar_forward(&scalar) + 0;
    let by_value = projection_value(ReferenceParcel.Present(73)) + 0;
    projection_write(&mut scalar, 91);
    let scalar_after = *projection_scalar_forward(&scalar) + 0;
    projection_record_write(&mut record, 79);
    let record_after = projection_forward(&record).value + 0;
    let padding = projection_forward(&record).padding + 0;
    print(f"projection field={field} method={method} scalar={scalar_before} value={by_value} mutable={scalar_after} record_mutable={record_after} padding={padding}");
    assert_eq(field + 0, 73);
    assert_eq(method + 0, 73);
    assert_eq(scalar_before + 0, 73);
    assert_eq(by_value + 0, 73);
    assert_eq(scalar_after + 0, 91);
    assert_eq(record_after + 0, 79);
    assert_eq(padding + 0, 11);

    print("reference_once_begin");
    let once = Once.new();
    once.call_once(|| { REFERENCE_ONCE_COUNT = REFERENCE_ONCE_COUNT + 1; });
    once.call_once(|| { REFERENCE_ONCE_COUNT = REFERENCE_ONCE_COUNT + 100; });
    let direct_count = REFERENCE_ONCE_COUNT + 0;
    let first: &Int = REFERENCE_SCALAR_CELL.get_or_init(reference_scalar_initialize);
    let second: &Int = REFERENCE_SCALAR_CELL.get_or_init(|| {
        REFERENCE_SCALAR_COUNT = REFERENCE_SCALAR_COUNT + 100;
        99
    });
    let first_value = *first + 0;
    let second_value = *second + 0;
    let scalar_count = REFERENCE_SCALAR_COUNT + 0;
    let record_first = reference_record_root().read() + 0;
    let record_second = reference_record_root().read() + 0;
    let record_count = REFERENCE_RECORD_COUNT + 0;
    print(f"once direct_count={direct_count} first={first_value} second={second_value} count={scalar_count} record_first={record_first} record_second={record_second} record_count={record_count}");
    assert_eq(direct_count + 0, 1);
    assert_eq(first_value + 0, 37);
    assert_eq(second_value + 0, 37);
    assert_eq(scalar_count + 0, 1);
    assert_eq(record_first + 0, 73);
    assert_eq(record_second + 0, 73);
    assert_eq(record_count + 0, 1);

    print("reference_supervisor_begin");
    let root = root_supervisor();
    let again = root_supervisor();
    let root_id = root.id().raw();
    let again_id = again.id().raw();
    let root_name = root.name();
    let again_name = again.name();
    print(f"supervisor root={root_id} again={again_id} name={root_name} again_name={again_name}");
    assert_eq(root_id, 0_u64);
    assert_eq(again_id, 0_u64);
    assert_eq(root_name, "root");
    assert_eq(again_name, "root");
    print("reference_projection_complete=true");
}

declaration-property-control.source:
module wide {
    public type Item is { left: Int, right: Int };
    public const CAP: Int = Item.size;
}
module narrow {
    public type Item is { value: Int };
}
mount wide as short;
type Cell is { size: Bool };
fn field(Cell: Cell) -> Bool { Cell.size }
fn width<T>() -> Int { T.size }
fn main() {
    print("property_begin");
    print(field(Cell { size: true }));
    print(short.Item.size);
    print((&unsafe Int).size);
    print(width<&unsafe Byte>());
    let bytes: [Byte; wide.CAP] = [0; wide.CAP];
    print(bytes.len());
    print("property_end");
}

primitive-hash-control.source:
// @test: differential
// @level: L0
// @tier: all
// @timeout: 1200000
// @tags: hash, collections, protocols, regression
// @expected-exit: 0
// @expected-stdout-begin
// hash=7:-1747035056885442531:-1747035056885442531:-1747035056885442531
// hash=0:0:0:0
// hash=-1:3346860396619971396:3346860396619971396:3346860396619971396
// hash=-9223372036854775808:-4728538181899302272:-4728538181899302272:-4728538181899302272
// hash=9223372036854775807:-1381677785279330876:-1381677785279330876:-1381677785279330876
// hash_user=37
// map_initial=5:221
// map_update=37:59
// map_remove=47:4:196:false
// set_initial=5:false:true
// set_remove=true:4:false:true
// @expected-stdout-end
// @description: Int hash agrees with DefaultHasher LE bytes; Map/Set key operations retain coherence.

mount core.base.protocols.{Hash, Hasher, DefaultHasher};

fn hash_value(value: Int) -> Int { value + 30 }

fn borrowed_hash(value: &Int) -> Int { value.hash_value() }

fn report_hash(value: Int, expected: Int) {
    let direct = value.hash_value();
    let mut hasher = DefaultHasher.new();
    hasher.write_int(value);
    let streamed = hasher.finish();
    let borrowed = borrowed_hash(&value);
    print(f"hash={value}:{direct}:{streamed}:{borrowed}");
    assert_eq(direct + 0, expected);
    assert_eq(streamed + 0, expected);
    assert_eq(borrowed + 0, expected);
}

fn main() {
    let minimum = -9223372036854775807 - 1;
    let maximum = 9223372036854775807;
    report_hash(7, -1747035056885442531);
    report_hash(0, 0);
    report_hash(-1, 3346860396619971396);
    report_hash(minimum, -4728538181899302272);
    report_hash(maximum, -1381677785279330876);
    let user = hash_value(7);
    print(f"hash_user={user}");
    assert_eq(user + 0, 37);

    let mut map = Map<Int, Int>.new();
    map.insert(7, 37);
    map.insert(0, 41);
    map.insert(-1, 43);
    map.insert(minimum, 47);
    map.insert(maximum, 53);
    let initial = map.get(7).unwrap_or(-999) + map.get(0).unwrap_or(-999)
        + map.get(-1).unwrap_or(-999) + map.get(minimum).unwrap_or(-999)
        + map.get(maximum).unwrap_or(-999);
    print(f"map_initial={map.len()}:{initial}");
    assert_eq(map.len(), 5);
    assert_eq(initial + 0, 221);
    let replaced = map.insert(7, 59).unwrap_or(-999);
    let updated = map.get(7).unwrap_or(-999);
    print(f"map_update={replaced}:{updated}");
    assert_eq(replaced + 0, 37);
    assert_eq(updated + 0, 59);
    let removed = map.remove(minimum).unwrap_or(-999);
    let remaining = map.get(7).unwrap_or(-999) + map.get(0).unwrap_or(-999)
        + map.get(-1).unwrap_or(-999) + map.get(maximum).unwrap_or(-999);
    let still_present = map.contains_key(minimum);
    print(f"map_remove={removed}:{map.len()}:{remaining}:{still_present}");
    assert_eq(removed + 0, 47);
    assert_eq(map.len(), 4);
    assert_eq(remaining + 0, 196);
    assert(!still_present);

    let mut set = Set<Int>.new();
    set.insert(7);
    set.insert(0);
    set.insert(-1);
    set.insert(minimum);
    set.insert(maximum);
    let duplicate = set.insert(7);
    let present = set.contains(minimum);
    print(f"set_initial={set.len()}:{duplicate}:{present}");
    assert_eq(set.len(), 5);
    assert(!duplicate);
    assert(present);
    let removed_set = set.remove(-1);
    let absent = set.contains(-1);
    let retained = set.contains(maximum);
    print(f"set_remove={removed_set}:{set.len()}:{absent}:{retained}");
    assert(removed_set);
    assert_eq(set.len(), 4);
    assert(!absent);
    assert(retained);
}

numeric-list-control.source:
mount core.*;

fn print_f32(value: Float32) { print(value); }

fn main() {
    print("numeric_begin");
    print(9001);
    print(true);
    print(0.0);
    print(-0.0);
    print(1.25);
    print(1.0e-7);
    print(-1.0e-7);
    print(1.0e20);
    print_f32(1.5 as Float32);
    print(false);
    print(-9002);
    let mut index = 0;
    while index < 2 { print(1.25); index += 1; }
    print("numeric_end");
    let mut values: List<Int> = List<Int>.new();
    values.reserve(3);
    values.push(7);
    values.shrink_to_fit();
    values.reserve(17);
    print(f"int_list_layout_control={values[0]}");
    values.clear();
    values.shrink_to_fit();
    values.reserve(2);
    values.push(37);
    print(f"int_list_empty_regrow={values[0]} len={values.len()}");
    let mut bytes: List<Byte> = List<Byte>.new();
    bytes.push(255 as Byte);
    bytes.push(42 as Byte);
    bytes.shrink_to_fit();
    bytes.reserve(17);
    bytes.swap(0, 1);
    let removed = bytes.remove(1);
    bytes.insert(1, removed);
    print(f"byte_list_values={bytes[0] as Int},{bytes[1] as Int}");
    bytes.clear();
    bytes.shrink_to_fit();
    bytes.reserve(2);
    bytes.push(37 as Byte);
    print(f"byte_list_empty_regrow={bytes[0] as Int} len={bytes.len()}");
    print("storage_control_end");
}

native-control.source:
// Combined diagnostic; lifecycle observations are evaluated separately.
mount core.base.memory.{Shared};
mount core.sync.atomic.{AtomicBool, AtomicInt, MemoryOrdering};

mount core.sync.mutex.{Mutex};
mount core.sys.common.{OSError};
mount core.sys.darwin.thread.{futex_wait};

type CounterCell is { padding: Int, value: Int };
type OuterCell is { padding: Int, inner: CounterCell };

fn reference_control() {
    let scoped: Mutex<Int> = Mutex.new(17);
    {
        let guard = scoped.lock().unwrap();
        print(f"scope_inside={scoped.is_locked()}");
    }
    print(f"scope_after={scoped.is_locked()}");
    let explicit: Mutex<Int> = Mutex.new(29);
    let guard = explicit.lock().unwrap();
    drop(guard);
    print(f"explicit_after={explicit.is_locked()}");
    let outer = OuterCell { padding: 91, inner: CounterCell { padding: 93, value: 7 } };
    print("pointer_probe_begin");
    let result: Result<(), OSError> = futex_wait(&outer.inner.value, 8, Maybe.None);
    print(f"pointer_probe_ok={result.is_ok()}");
}

type PredicateNumbers is { base: Int };

implement PredicateNumbers {
    fn is_ok(&self) -> Int { self.base + 1 }
    fn is_err(&self) -> Int { self.base + 2 }
}

fn predicate_control() {
    let good: Result<Int, Int> = Result.Ok(7);
    let bad: Result<Int, Int> = Result.Err(9);
    print(good.is_ok());
    print(good.is_err());
    print(bad.is_ok());
    print(bad.is_err());

    let numbers = PredicateNumbers { base: 9000 };
    print(numbers.is_ok());
    print(numbers.is_err());
}
fn atomic_control() {
    let plain = AtomicBool.new(true);
    print(f"plain_load={plain.load(MemoryOrdering.SeqCst)}");
    print(f"plain_swap={plain.swap(false, MemoryOrdering.SeqCst)}");
    print(f"plain_after={plain.load(MemoryOrdering.SeqCst)}");
    let shared = Shared.new(AtomicBool.new(true));
    print(f"shared_load={shared.load(MemoryOrdering.SeqCst)}");
    print(f"shared_swap={shared.swap(false, MemoryOrdering.SeqCst)}");
    print(f"shared_after={shared.load(MemoryOrdering.SeqCst)}");
    let number = AtomicInt.new(73);
    print(f"integer_swap={number.swap(91, MemoryOrdering.SeqCst)}");
    print(f"integer_after={number.load(MemoryOrdering.SeqCst)}");
}

fn scalar_suite() {
    print("phase=atomics");
    atomic_control();
    print("phase=predicates");
    predicate_control();
    print("phase=references");
    reference_control();
    print("reference_scalar_completed=true");
}

fn hash_value(value: Int) -> Int { value + 30 }
fn hash_control() {
    print("phase=hash_dispatch");
    print(f"hash_user={hash_value(7)}");
    let key: Int = 7;
    print(f"hash_builtin={key.hash_value()}");
}
fn main() {
    scalar_suite();
    hash_control();
    print("native_acceptance_completed=true");
}

